INSERT INTO game_roles VALUES('FC26','cb_wideback','와이드 백',NULL,'CB','["Support", "Aggressive", "Defend"]','풀백 뒤를 커버하며 측면까지 넓게 막는 센터백(백3의 바깥).','포커스가 **측면으로 얼마나 나가나**를 바꾼다 — Defend 라인 · Aggressive 4줄 · Support 3줄까지.');
