INSERT INTO game_roles VALUES('FC26','wm_insidefwd','인사이드 포워드',NULL,'WM','["Balanced", "Attack"]','미드필드 라인에서 출발해 하프스페이스로 파고드는 측면 공격수.','포커스가 **뒤로 뛰나, 발밑으로 받나**를 바꾼다(W 인사이드 포워드와 같은 축).');
