INSERT INTO game_roles VALUES('FC26','st_advanced','어드밴스드 포워드',NULL,'ST','["Support", "Attack", "Versatile"]','득점하면서 공도 받아 주는 공격수.','포커스가 **출발 위치**를 바꾼다 — Attack 중앙 · Versatile 측면 이탈 · Support 깊은 곳·하프스페이스.');
