INSERT INTO game_roles VALUES('FC26','st_target','타깃 포워드',NULL,'ST','["Attack", "Balanced", "Wide"]','등지고 버티는 기준점.','포커스가 **기준점의 위치**를 바꾼다 — Attack 최전방 · Balanced 한 줄 아래 중앙 · Wide 박스 가장자리.');
INSERT INTO game_roles VALUES('FC26','st_false9','폴스 나인',NULL,'ST','["Attack", "Build-Up"]','내려와서 연결하는 공격수.','포커스가 **내려온 뒤 다시 들어가나**를 바꾼다 — Attack 다시 침투 · Build-Up 내려온 채 조립.');
